-- ============================================================
-- BI-360-Report | Camada de Staging (dados brutos das 13 fontes)
-- Portfólio: Nathália Paccelly | github.com/NPaccelly
-- Dialeto de referência: PostgreSQL / MySQL 8+ (compatível com pequenos
-- ajustes em SQL Server: trocar TEXT por VARCHAR e REAL por DECIMAL)
-- ============================================================



-- 1) Vendas Varejo (loja física) — granularidade: 1 linha por venda/produto/dia
--    Data em formato brasileiro DD/MM/AAAA
DROP TABLE IF EXISTS stg_vendas_varejo;
CREATE TABLE stg_vendas_varejo (
    Data_Venda      VARCHAR(10),
    Cod_Loja        VARCHAR(5),
    Nome_Loja       VARCHAR(60),
    Cod_Produto     VARCHAR(5),
    Qtd_Vendida     INTEGER,
    Preco_Unit_RS   DECIMAL(10,2),
    Valor_Total_RS  DECIMAL(10,2)
);



-- 2) Vendas E-commerce — granularidade: 1 linha por pedido/SKU
--    Data em formato ISO AAAA-MM-DD; inclui desconto de cupom e frete
DROP TABLE IF EXISTS stg_vendas_ecommerce;
CREATE TABLE stg_vendas_ecommerce (
    order_date      DATE,
    sku             VARCHAR(5),
    quantity        INTEGER,
    unit_price      DECIMAL(10,2),
    discount_pct    DECIMAL(5,2),
    shipping_fee    DECIMAL(10,2),
    gross_value     DECIMAL(10,2),
    net_value       DECIMAL(10,2)
);



-- 3) Campanhas Meta Ads — granularidade: 1 linha por campanha/dia
DROP TABLE IF EXISTS stg_campanhas_meta_ads;
CREATE TABLE stg_campanhas_meta_ads (
    date            DATE,
    campaign_id     VARCHAR(5),
    campaign_name   VARCHAR(60),
    impressions     INTEGER,
    clicks          INTEGER,
    spend_brl       DECIMAL(10,2),
    conversions     INTEGER
);



-- 4) Campanhas Google Ads — granularidade: 1 linha por campanha/dia
DROP TABLE IF EXISTS stg_campanhas_google_ads;
CREATE TABLE stg_campanhas_google_ads (
    date            DATE,
    campaign_id     VARCHAR(5),
    campaign_name   VARCHAR(60),
    impressions     INTEGER,
    clicks          INTEGER,
    spend_brl       DECIMAL(10,2),
    conversions     INTEGER
);



-- 5) Campanhas TikTok Ads — granularidade: 1 linha por campanha/dia
DROP TABLE IF EXISTS stg_campanhas_tiktok_ads;
CREATE TABLE stg_campanhas_tiktok_ads (
    date            DATE,
    campaign_id     VARCHAR(5),
    campaign_name   VARCHAR(60),
    impressions     INTEGER,
    clicks          INTEGER,
    spend_brl       DECIMAL(10,2),
    conversions     INTEGER
);



-- 6) Cadastro de Produtos (dimensão)
DROP TABLE IF EXISTS stg_cadastro_produtos;
CREATE TABLE stg_cadastro_produtos (
    cod_produto     VARCHAR(5),
    descricao       VARCHAR(80),
    categoria       VARCHAR(30),
    preco_venda     DECIMAL(10,2),
    custo_unitario  DECIMAL(10,2)
);



-- 7) Cadastro de Lojas (dimensão)
DROP TABLE IF EXISTS stg_cadastro_lojas;
CREATE TABLE stg_cadastro_lojas (
    cod_loja        VARCHAR(5),
    nome_loja       VARCHAR(60),
    cidade_uf       VARCHAR(40),
    regiao          VARCHAR(20)
);



-- 8) Cadastro de Clientes (CRM) — granularidade: 1 linha por cliente
--    Nomenclatura de colunas divergente das demais fontes (espaços, PT-BR)
DROP TABLE IF EXISTS stg_cadastro_clientes_crm;
CREATE TABLE stg_cadastro_clientes_crm (
    "ID Cliente"                VARCHAR(10),
    "Data Cadastro"             VARCHAR(10),
    "Regiao"                    VARCHAR(20),
    "Canal Preferido"           VARCHAR(20),
    "Ticket Medio Historico"    DECIMAL(10,2),
    "Opt-in Marketing"          VARCHAR(5)
);



-- 9) Financeiro — Custos (granularidade mensal por centro de custo)
--    Mes_Ref em formato MM/AAAA
DROP TABLE IF EXISTS stg_financeiro_custos;
CREATE TABLE stg_financeiro_custos (
    Mes_Ref         VARCHAR(7),
    Centro_Custo    VARCHAR(30),
    Valor_RS        DECIMAL(12,2)
);



-- 10) Financeiro — Receita (granularidade mensal)
--     competencia em formato AAAA-MM (diferente do padrão de custos)
DROP TABLE IF EXISTS stg_financeiro_receita;
CREATE TABLE stg_financeiro_receita (
    competencia         VARCHAR(7),
    tipo_receita         VARCHAR(30),
    valor_liquido_brl    DECIMAL(12,2)
);



-- 11) Calendário de Promoções / Eventos
DROP TABLE IF EXISTS stg_calendario_promocoes;
CREATE TABLE stg_calendario_promocoes (
    id_evento       VARCHAR(5),
    nome_evento     VARCHAR(60),
    data_inicio     DATE,
    data_fim        DATE,
    tipo            VARCHAR(20)
);



-- 12) Pesquisa de Satisfação (NPS) — granularidade: 1 linha por resposta
DROP TABLE IF EXISTS stg_pesquisa_satisfacao_nps;
CREATE TABLE stg_pesquisa_satisfacao_nps (
    resposta_id      VARCHAR(10),
    data_resposta    VARCHAR(10),
    loja_ou_canal    VARCHAR(60),
    nota_0_10        INTEGER,
    comentario_flag  VARCHAR(5)
);



-- 13) Cadastro de Campanhas (dimensão-mestre, une as 3 plataformas de mídia)
DROP TABLE IF EXISTS stg_cadastro_campanhas;
CREATE TABLE stg_cadastro_campanhas (
    cod_campanha    VARCHAR(5),
    nome_campanha   VARCHAR(60),
    data_inicio     DATE,
    data_fim        DATE,
    plataforma      VARCHAR(20)
);

